{w:"Osmose", a:"die", pos:"noun · feminine", ipa:"ˌɔsˈmoːzə", en:"osmosis, diffusion through a membrane", pl:"Plural: die Osmosen", ex:"Durch Osmose werden Konzentrationsunterschiede von Flüssigkeiten, die durch Membranen getrennt sind, ausgeglichen.", exEn:"Osmosis equalises differences in concentration between liquids separated by membranes.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Osmose"},
{w:"Entropie", a:"die", pos:"noun · feminine", ipa:"ɛntʁoˈpiː", en:"entropy, a measure of disorder", pl:"Plural: die Entropien", ex:"Die Entropie des Weltalls ist nicht berechenbar.", exEn:"The entropy of the universe cannot be calculated.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Entropie"},
{w:"Isotop", a:"das", pos:"noun · neuter", ipa:"izoˈtoːp", en:"isotope, an atom variant of an element", pl:"Plural: die Isotope", ex:"Das Element Wasserstoff (H) hat drei Isotope: 1H (Protium) ohne Neutron, Deuterium mit einem Neutron und Tritium mit zwei Neutronen, jeweils mit einem Proton.", exEn:"The element hydrogen (H) has three isotopes: 1H (protium) with no neutron, deuterium with one neutron and tritium with two neutrons, each with one proton.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Isotop"},
{w:"Katalysator", a:"der", pos:"noun · masculine", ipa:"katalyˈzaːtoːɐ̯", en:"catalyst, a substance that speeds up a reaction", pl:"Plural: die Katalysatoren", ex:"Bei vielen chemischen Reaktionen werden Katalysatoren zur Reaktionsbeschleunigung verwendet.", exEn:"Catalysts are used in many chemical reactions to speed them up.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Katalysator"},
{w:"Chromosom", a:"das", pos:"noun · neuter", ipa:"kʁomoˈzoːm", en:"chromosome, carrier of genetic information", pl:"Plural: die Chromosomen", ex:"Der Mensch hat 46 Chromosomen.", exEn:"Humans have 46 chromosomes.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Chromosom"},
{w:"Genotyp", a:"der", pos:"noun · masculine", ipa:"ɡenoˈtyːp", en:"genotype, the sum of an organism's genes", pl:"Plural: die Genotypen", ex:"Die Genotypen der beiden Generationen unterscheiden sich signifikant.", exEn:"The genotypes of the two generations differ significantly.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Genotyp"},
{w:"Phänotyp", a:"der", pos:"noun · masculine", ipa:"ˈfɛːnoˌtyːp", en:"phenotype, the visible traits of an organism", pl:"Plural: die Phänotypen", ex:"Die Phänotypen der beiden Schwesterarten unterscheiden sich deutlich voneinander.", exEn:"The phenotypes of the two sister species differ clearly from each other.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Ph%C3%A4notyp"},
{w:"Taxonomie", a:"die", pos:"noun · feminine", ipa:"ˌtaksonoˈmiː", en:"taxonomy, the classification of organisms", pl:"Plural: die Taxonomien", ex:"Die Taxonomie der Reptilien befindet sich gerade im Umbruch.", exEn:"The taxonomy of reptiles is currently in upheaval.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Taxonomie"},
{w:"Supraleitung", a:"die", pos:"noun · feminine", ipa:"ˈzuːpʁaˌlaɪ̯tʊŋ", en:"superconductivity, zero electrical resistance at low temperature", pl:"No plural", ex:"Am Quecksilber wurde vom niederländischen Physiker Heike Kamerlingh Onnes im Jahre 1911 das erste Mal das Phänomen der Supraleitung entdeckt.", exEn:"The phenomenon of superconductivity was first discovered in mercury by the Dutch physicist Heike Kamerlingh Onnes in 1911.", lv:3, field:"Natural sciences", archaic:false, src:"https://de.wiktionary.org/wiki/Supraleitung"},
{w:"Dasein", a:"das", pos:"noun · neuter", ipa:"ˈdaːˌzaɪ̯n", en:"existence, being in the world", pl:"No plural", ex:"Sie freuten sich ihres Daseins.", exEn:"They rejoiced in their existence.", note:"Central term in Heidegger's philosophy.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Dasein"},
{w:"Weltanschauung", a:"die", pos:"noun · feminine", ipa:"ˈvɛltʔanˌʃaʊ̯ʊŋ", en:"worldview, a system of ideas about the world", pl:"Plural: die Weltanschauungen", ex:"Es gibt mehrere unterschiedliche Weltanschauungen.", exEn:"There are several different worldviews.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Weltanschauung"},
{w:"Aufhebung", a:"die", pos:"noun · feminine", ipa:"ˈaʊ̯fˌheːbʊŋ", en:"sublation, abolition that also preserves and lifts up", pl:"Plural: die Aufhebungen", ex:"Die Aufhebung des Jesuitenordens erfolgte 1773 durch Papst Clemens XIV. auf Druck der Könige von Frankreich, Spanien und Portugal.", exEn:"The suppression of the Jesuit order took place in 1773 by Pope Clement XIV under pressure from the kings of France, Spain and Portugal.", note:"Hegel's term: to cancel, to preserve and to lift up at once.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Aufhebung"},
{w:"Ontologie", a:"die", pos:"noun · feminine", ipa:"ˌɔntoloˈɡiː", en:"ontology, the study of being and existence", pl:"Plural: die Ontologien", ex:"Die Frage nach dem Seienden und dem Sein, […] ist die Kernfrage der Ontologie und die schwierigste und abstrakteste Frage der ganzen Philosophie überhaupt.", exEn:"The question of beings and of Being is the central question of ontology and the most difficult and abstract question in all of philosophy.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Ontologie"},
{w:"Phänomenologie", a:"die", pos:"noun · feminine", ipa:"fɛnomenoloˈɡiː", en:"phenomenology, the study of phenomena as experienced", pl:"No plural", ex:"Da Wissenschaft an sich eine Lehre der Erscheinungen und ihrer Zusammenhänge ist, bezeichnet Phänomenologie eine Methodik, die die deskriptiven Aspekte der Wissenschaft gegen die experimentellen und theoretischen Methoden abgrenzt.", exEn:"Since science in itself is the study of appearances and their connections, phenomenology denotes a method that sets the descriptive aspects of science apart from experimental and theoretical methods.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Ph%C3%A4nomenologie"},
{w:"Hermeneutik", a:"die", pos:"noun · feminine", ipa:"ˌhɛʁmeˈnɔɪ̯tɪk", en:"hermeneutics, the art of interpretation", pl:"Plural: die Hermeneutiken", ex:"Hermeneutik dient dem Verstehen einer Sache, die nicht wie beim „Erklären“ als unabhängiger, beliebiger Gegenstand dem Verstand äußerlich bleibt, sondern selbst als von individuellen und kollektiven, bleibenden und geschichtlichen Momenten durchdrungene Substanz der Erfahrung intersubjektiven Einverständnisses zugehört und entspricht.", exEn:"Hermeneutics serves to understand something that, unlike in 'explaining', does not remain external to the mind as an independent, arbitrary object, but belongs to and corresponds with the substance of experience of intersubjective agreement, permeated by individual and collective, lasting and historical moments.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Hermeneutik"},
{w:"Solipsismus", a:"der", pos:"noun · masculine", ipa:"zolɪˈpsɪsmʊs", en:"solipsism, the view that only one's own mind exists", pl:"No plural", ex:"Und natürlich ist der Solipsismus auch nie als ernsthafte Überzeugung von einem gesunden Menschen vertreten worden (wem gegenüber auch?); er gehört vielmehr ausschließlich ins philosophische Denklabor und wird dort gelegentlich als eine rein methodische Fiktion herangezogen, […]", exEn:"And of course solipsism has never been held as a serious conviction by a sane person (held against whom?); it belongs exclusively in the philosophical thought laboratory, where it is occasionally used as a purely methodological fiction.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Solipsismus"},
{w:"Dialektik", a:"die", pos:"noun · feminine", ipa:"diaˈlɛktɪk", en:"dialectic, reasoning through thesis and antithesis", pl:"No plural", ex:"Zum ersten Mal findet sich der Ausdruck Dialektik bei Platon.", exEn:"The term dialectic is found for the first time in Plato.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Dialektik"},
{w:"Transzendenz", a:"die", pos:"noun · feminine", ipa:"tʁanst͡sɛnˈdɛnt͡s", en:"transcendence, what lies beyond experience", pl:"Plural: die Transzendenzen", ex:"Als methodologisch ist Transzendenz dort zu bestimmen, wo sie – wie besonders bei Heidegger und Jaspers – ein Überschreiten aller Gegenständlichkeit als Charakteristikum wirklichen Philosophierens meint.", exEn:"Methodologically, transcendence is to be located where, as especially in Heidegger and Jaspers, it means going beyond all objectivity as the hallmark of genuine philosophising.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Transzendenz"},
{w:"Erkenntnistheorie", a:"die", pos:"noun · feminine", ipa:"ɛɐ̯ˈkɛntnɪsteoˌʁiː", en:"epistemology, the theory of knowledge", pl:"No plural", ex:"Die Erkenntnistheorie sichert die Wahrheitsbefähigung unseres Geistes, der das Seiende erfassen kann.", exEn:"Epistemology secures our mind's capacity for truth, which can grasp what is.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Erkenntnistheorie"},
{w:"Metaphysik", a:"die", pos:"noun · feminine", ipa:"ˈmeːtafyˌziːk", en:"metaphysics, the study of first principles", pl:"No plural", ex:"Immanuel Kant kritisierte die Metaphysik aufgrund ihres vermeintlich fehlenden intersubjektiv überprüfbaren Erfahrungsbezuges.", exEn:"Immanuel Kant criticised metaphysics for its supposedly lacking intersubjectively verifiable relation to experience.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Metaphysik"},
{w:"Nihilismus", a:"der", pos:"noun · masculine", ipa:"ˌnihiˈlɪsmʊs", en:"nihilism, denial of objective meaning or values", pl:"No plural", ex:"Nicht nur der Nihilismus, sondern auch der religiöse Fanatismus, der heute oft als Fundamentalismus bezeichnet wird, kann terroristische Vorhaben und Handlungen inspirieren […].", exEn:"Not only nihilism but also religious fanaticism, today often called fundamentalism, can inspire terrorist plans and actions.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Nihilismus"},
{w:"Existenzialismus", a:"der", pos:"noun · masculine", ipa:"ɛksɪstɛnt͡si̯aˈlɪsmʊs", en:"existentialism, existence before essence", pl:"No plural", ex:"Eine der grundlegenden Annahmen des Existenzialismus und seiner Vertreter ist der Glaube an die Freiheit des menschlichen Individuums.", exEn:"One of the basic assumptions of existentialism and its proponents is the belief in the freedom of the human individual.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Existenzialismus"},
{w:"Vernunft", a:"die", pos:"noun · feminine", ipa:"fɛɐ̯ˈnʊnft", en:"reason, the faculty of rational thought", pl:"No plural", ex:"Nur der Mensch ist zur Vernunft fähig.", exEn:"Only humans are capable of reason.", lv:3, field:"Philosophy", archaic:false, src:"https://de.wiktionary.org/wiki/Vernunft"},
{w:"Verdrängung", a:"die", pos:"noun · feminine", ipa:"fɛɐ̯ˈdʁɛŋʊŋ", en:"repression, pushing unpleasant thoughts out of mind", pl:"Plural: die Verdrängungen", ex:"Die Verdrängung des eigenen Todes ist bei uns üblich.", exEn:"Repressing the thought of one's own death is common among us.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Verdr%C3%A4ngung"},
{w:"Fehlleistung", a:"die", pos:"noun · feminine", ipa:"ˈfeːlˌlaɪ̯stʊŋ", en:"slip, an unintended faulty action or utterance", pl:"Plural: die Fehlleistungen", ex:"Vergessen, Verlesen sind Fehlleistungen.", exEn:"Forgetting and misreading are slips.", note:"Example from DWDS; definition verified in German Wiktionary.", lv:3, field:"Psychology", archaic:false, src:"https://www.dwds.de/wb/Fehlleistung"},
{w:"Projektion", a:"die", pos:"noun · feminine", ipa:"pʁojɛkˈt͡si̯oːn", en:"projection, attributing one's own feelings to others", pl:"Plural: die Projektionen", ex:"Projektion bedeutet, eigene Anteile an sich nicht zu sehen, sondern sie auf den anderen zu transferieren und dort zu bekämpfen.", exEn:"Projection means not seeing parts of oneself, but transferring them onto the other person and fighting them there.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Projektion"},
{w:"Dissoziation", a:"die", pos:"noun · feminine", ipa:"dɪsot͡si̯aˈt͡si̯oːn", en:"dissociation, a break in the integration of consciousness", pl:"Plural: die Dissoziationen", ex:"Bei der Patientin löst dieser Gegenstand eine Dissoziation aus.", exEn:"In this patient, the object triggers a dissociation.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Dissoziation"},
{w:"Narzissmus", a:"der", pos:"noun · masculine", ipa:"naʁˈt͡sɪsmʊs", en:"narcissism, excessive self-love", pl:"Plural: die Narzissmen", ex:"Narzissmus ist nicht nur Selbstliebe, denn er geht Hand in Hand mit mangelndem Mitgefühl für und fehlender Solidarität mit anderen.", exEn:"Narcissism is not only self-love, for it goes hand in hand with a lack of empathy for and solidarity with others.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Narzissmus"},
{w:"Archetyp", a:"der", pos:"noun · masculine", ipa:"ˌaʁçeˈtyːp", en:"archetype, an original pattern or model", pl:"Plural: die Archetypen", ex:"Holden Caulfield, in seiner spöttischen Verweigerung und Rebellion, wurde zum Archetyp für Generationen von Jugendlichen, denen das Buch bald als Schullektüre begegnete.", exEn:"Holden Caulfield, in his mocking refusal and rebellion, became the archetype for generations of young people who soon met the book as school reading.", note:"In Jung's psychology, an archetype is an inherited pattern of the collective unconscious.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Archetyp"},
{w:"Konditionierung", a:"die", pos:"noun · feminine", ipa:"kɔndit͡si̯oˈniːʁʊŋ", en:"conditioning, learning through repeated stimulus", pl:"Plural: die Konditionierungen", ex:"Ein unkonditionierter Stimulus (UCS für unconditioned stimuli) ist ein Reiz, der ohne Konditionierung, also ohne Lernen eine Reaktion / einen Reflex auslöst.", exEn:"An unconditioned stimulus (UCS) is a stimulus that triggers a reaction or reflex without conditioning, that is, without learning.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Konditionierung"},
{w:"Kognition", a:"die", pos:"noun · feminine", ipa:"ˌkɔɡniˈt͡si̯oːn", en:"cognition, mental processes of knowing", pl:"Plural: die Kognitionen", ex:"Kognitionen sind zum Beispiel Meinungen, Einstellungen, Wünsche und Absichten eines Menschen.", exEn:"Cognitions are, for example, a person's opinions, attitudes, wishes and intentions.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Kognition"},
{w:"Trieb", a:"der", pos:"noun · masculine", ipa:"tʁiːp", en:"drive, an inner urge or instinct", pl:"Plural: die Triebe", ex:"Man kann es drehen und wenden, wie man will, der Sexualtrieb ist eindeutig der stärkste und rücksichtsloseste Trieb überhaupt.", exEn:"Turn it how you will, the sexual drive is clearly the strongest and most ruthless drive of all.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Trieb"},
{w:"Libido", a:"die", pos:"noun · feminine", ipa:"ˈliːbido", en:"libido, sexual drive", pl:"No plural", ex:"Diese Lebensmittel sollen die Libido steigern.", exEn:"These foods are said to increase the libido.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Libido"},
{w:"Resilienz", a:"die", pos:"noun · feminine", ipa:"ʁeziˈli̯ɛnt͡s", en:"resilience, the ability to bounce back", pl:"Plural: die Resilienzen", ex:"Ein anschauliches Beispiel für Resilienz im engeren Sinn ist die Fähigkeit von Stehaufmännchen, sich aus jeder beliebigen Lage wieder aufzurichten.", exEn:"A vivid example of resilience in the narrower sense is the ability of a roly-poly toy to right itself from any position.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Resilienz"},
{w:"Komplex", a:"der", pos:"noun · masculine", ipa:"kɔmˈplɛks", en:"complex, a repressed group of ideas that causes unease", pl:"Plural: die Komplexe", ex:"Er steckt so voller Komplexe, dass er sich kaum unter Menschen zu gehen traut.", exEn:"He is so full of complexes that he hardly dares to go out among people.", lv:3, field:"Psychology", archaic:false, src:"https://de.wiktionary.org/wiki/Komplex"},
{w:"Mittelstand", a:"der", pos:"noun · masculine", ipa:"ˈmɪtl̩ˌʃtant", en:"Mittelstand, Germany's small and medium-sized firms", pl:"No plural", ex:"Dieser alte Handwerksbetrieb gehört zum Mittelstand.", exEn:"This old craft business is part of the Mittelstand.", note:"The backbone of the German economy; no clean one-word equivalent in English.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Mittelstand"},
{w:"Mitbestimmung", a:"die", pos:"noun · feminine", ipa:"ˈmɪtbəˌʃtɪmʊŋ", en:"co-determination, workers' say in company decisions", pl:"Plural: die Mitbestimmungen", ex:"Den Arbeitern wurde ein Recht auf Mitbestimmung eingeräumt.", exEn:"The workers were granted a right of co-determination.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Mitbestimmung"},
{w:"Schuldenbremse", a:"die", pos:"noun · feminine", ipa:"ˈʃʊldn̩ˌbʁɛmzə", en:"debt brake, constitutional limit on state borrowing", pl:"Plural: die Schuldenbremsen", ex:"Die Schweizer Schuldenbremse funktioniert nach dem Prinzip von Grossmutters Haushaltsbüchlein. Der Staat darf über die Dauer nicht mehr ausgeben, als er einnimmt.", exEn:"The Swiss debt brake works on the principle of grandmother's household ledger. Over time, the state may not spend more than it takes in.", note:"Constitutional rule limiting state borrowing.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Schuldenbremse"},
{w:"Konjunktur", a:"die", pos:"noun · feminine", ipa:"kɔnjʊŋkˈtuːɐ̯", en:"the economy, the state of business activity", pl:"Plural: die Konjunkturen", ex:"Die gute Konjunktur sorgt für mehr Arbeitsplätze.", exEn:"The strong economy creates more jobs.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Konjunktur"},
{w:"Bruttoinlandsprodukt", a:"das", pos:"noun · neuter", ipa:"ˌbʁʊtoˈʔɪnlant͡spʁoˌdʊkt", en:"gross domestic product (GDP)", pl:"Plural: die Bruttoinlandsprodukte", ex:"Das Bruttoinlandsprodukt stieg von Juli bis September um 0,5 Prozent im Vergleich zum Frühjahr, teilte das Statistische Bundesamt mit.", exEn:"Gross domestic product rose by 0.5 percent from July to September compared with the spring, the Federal Statistical Office announced.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Bruttoinlandsprodukt"},
{w:"Zahlungsbilanz", a:"die", pos:"noun · feminine", ipa:"ˈt͡saːlʊŋsbiˌlant͡s", en:"balance of payments", pl:"Plural: die Zahlungsbilanzen", ex:"Die Zahlungsbilanz ist aktiv, wenn ein Zahlungsrest des Auslands an das Inland, passiv, wenn ein Zahlungsrest des Inlands an das Ausland verbleibt.", exEn:"The balance of payments is in surplus when a payment balance remains owed by foreign countries to the home country, and in deficit when the reverse holds.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Zahlungsbilanz"},
{w:"Inflation", a:"die", pos:"noun · feminine", ipa:"ɪnflaˈt͡si̯oːn", en:"inflation, sustained rise in prices", pl:"Plural: die Inflationen", ex:"Die Inflation in Deutschland ist 2022 so hoch ausgefallen wie noch nie. Die Verbraucherpreise erhöhten sich um durchschnittlich 7,9 Prozent [...].", exEn:"Inflation in Germany in 2022 was higher than ever before. Consumer prices rose by an average of 7.9 percent.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Inflation"},
{w:"Rezession", a:"die", pos:"noun · feminine", ipa:"ʁet͡sɛˈsi̯oːn", en:"recession, a period of shrinking output", pl:"Plural: die Rezessionen", ex:"Eine Rezession liegt vor, wenn das Bruttoinlandsprodukt in zwei aufeinanderfolgenden Quartalen abnimmt.", exEn:"A recession exists when gross domestic product falls in two consecutive quarters.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Rezession"},
{w:"Leitzins", a:"der", pos:"noun · masculine", ipa:"ˈlaɪ̯tˌt͡sɪns", en:"key interest rate set by a central bank", pl:"Plural: die Leitzinsen", ex:"Die Zentralbank senkte erneut den Leitzins.", exEn:"The central bank lowered the key interest rate again.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Leitzins"},
{w:"Wechselkurs", a:"der", pos:"noun · masculine", ipa:"ˈvɛksl̩ˌkʊʁs", en:"exchange rate", pl:"Plural: die Wechselkurse", ex:"Wechselkurse zu beobachten ist nicht nur etwas für Börsenspekulanten, es kann sich auch für Urlauber auszahlen.", exEn:"Watching exchange rates is not only for stock market speculators; it can also pay off for holidaymakers.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Wechselkurs"},
{w:"Handelsbilanz", a:"die", pos:"noun · feminine", ipa:"ˈhandl̩sbiˌlant͡s", en:"trade balance, exports set against imports", pl:"Plural: die Handelsbilanzen", ex:"Übersteigt die Summe der Ausfuhren die Summe der Einfuhren, so spricht man von einer aktiven (bzw. positiven) Handelsbilanz, im umgekehrten Fall, also wenn die Importe die Exporte übersteigen, von einer passiven (bzw. negativen) Handelsbilanz.", exEn:"If exports exceed imports, one speaks of an active (positive) trade balance; in the opposite case, when imports exceed exports, of a passive (negative) trade balance.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Handelsbilanz"},
{w:"Gewerkschaft", a:"die", pos:"noun · feminine", ipa:"ɡəˈvɛʁkʃaft", en:"trade union", pl:"Plural: die Gewerkschaften", ex:"Die Gewerkschaften riefen einen Streik aus.", exEn:"The trade unions called a strike.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Gewerkschaft"},
{w:"Betriebsrat", a:"der", pos:"noun · masculine", ipa:"bəˈtʁiːpsˌʁaːt", en:"works council, elected staff representatives", pl:"Plural: die Betriebsräte", ex:"Ob sie denn keinen Betriebsrat hätten, wollte Marga wissen.", exEn:"'Don't you have a works council?' Marga wanted to know.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Betriebsrat"},
{w:"Streik", a:"der", pos:"noun · masculine", ipa:"ʃtʁaɪ̯k", en:"strike, collective stoppage of work", pl:"Plural: die Streiks", ex:"Die Erfolgsaussichten dieses Streiks waren von vornherein schlecht.", exEn:"This strike's chances of success were poor from the outset.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Streik"},
{w:"Tarifvertrag", a:"der", pos:"noun · masculine", ipa:"taˈʁiːffɛɐ̯ˌtʁaːk", en:"collective agreement on pay and conditions", pl:"Plural: die Tarifverträge", ex:"Ursprünglich wollten die Fluglotsen am Donnerstag von 6 bis 12 Uhr bundesweit die Arbeit niederlegen, nachdem sich die Gewerkschaft nicht mit der DFS auf einen neuen Tarifvertrag einigen konnte.", exEn:"The air traffic controllers had originally planned to stop work nationwide on Thursday from 6 a.m. to noon after the union failed to agree a new collective agreement with DFS.", lv:3, field:"Economics", archaic:false, src:"https://de.wiktionary.org/wiki/Tarifvertrag"},
{w:"Fachwerk", a:"das", pos:"noun · neuter", ipa:"ˈfaxˌvɛʁk", en:"half-timbering, timber-frame construction", pl:"Plural: die Fachwerke", ex:"Alte Städte zieren sich oft noch mit viel Fachwerk.", exEn:"Old towns still often adorn themselves with much half-timbering.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Fachwerk"},
{w:"Zunft", a:"die", pos:"noun · feminine", ipa:"t͡sʊnft", en:"guild, medieval craft association", pl:"Plural: die Zünfte", ex:"Die Gesellen, die ihre Meisterprüfung ablegen wollten, hatten je nach Stadt, Zunft und historischer Zeit verschiedene Bedingungen zu erfüllen.", exEn:"Journeymen who wanted to take their master craftsman's examination had to meet different conditions depending on the town, the guild and the historical period.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Zunft"},
{w:"Schraubstock", a:"der", pos:"noun · masculine", ipa:"ˈʃʁaʊ̯pˌʃtɔk", en:"vice, a clamping tool", pl:"Plural: die Schraubstöcke", ex:"Ein Schraubstock besteht aus einer beweglichen und einer unbeweglichen Backe.", exEn:"A vice consists of a movable and a fixed jaw.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Schraubstock"},
{w:"Hobel", a:"der", pos:"noun · masculine", ipa:"ˈhoːbl̩", en:"plane, a woodworking tool", pl:"Plural: die Hobel", ex:"Der Hobel ist das wichtigste Werkzeug des Schreiners.", exEn:"The plane is the joiner's most important tool.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Hobel"},
{w:"Lehrling", a:"der", pos:"noun · masculine", ipa:"ˈleːɐ̯lɪŋ", en:"apprentice", pl:"Plural: die Lehrlinge", ex:"Als ich Lehrling war, musste ich meist die ganze Halle fegen.", exEn:"When I was an apprentice, I usually had to sweep the whole hall.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Lehrling"},
{w:"Geselle", a:"der", pos:"noun · masculine", ipa:"ɡəˈzɛlə", en:"journeyman, a qualified craftsman", pl:"Plural: die Gesellen", ex:"Aufgrund seiner guten Prüfung wurde der Geselle im Betrieb übernommen.", exEn:"Because of his good examination, the journeyman was taken on permanently by the firm.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Geselle"},
{w:"Werkstück", a:"das", pos:"noun · neuter", ipa:"ˈvɛʁkˌʃtʏk", en:"workpiece, a part being machined", pl:"Plural: die Werkstücke", ex:"Laut DIN 8580 ist ein Werkstück ein Einzelteil eines technischen Gebildes in der Fertigung.", exEn:"According to DIN 8580, a workpiece is an individual part of a technical product in manufacturing.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Werkst%C3%BCck"},
{w:"Schmiede", a:"die", pos:"noun · feminine", ipa:"ˈʃmiːdə", en:"forge, a smithy", pl:"Plural: die Schmieden", ex:"Den Besuchern schlagen das Dröhnen der Schmieden und der Gestank von Tausend Misthaufen entgegen.", exEn:"Visitors are met by the roar of the forges and the stench of a thousand dung heaps.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Schmiede"},
{w:"Zimmermann", a:"der", pos:"noun · masculine", ipa:"ˈt͡sɪmɐˌman", en:"carpenter, a timber construction worker", pl:"Plural: die Zimmermänner", ex:"Dachdecker, Zimmermänner und alle sonstigen Berufsgruppen, die sich auf Baustellen herumtummeln, sollten sich mit den Fachbegriffen rund ums Dach auskennen.", exEn:"Roofers, carpenters and all other trades found on building sites should know the technical terms for roofs.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Zimmermann"},
{w:"Tischler", a:"der", pos:"noun · masculine", ipa:"ˈtɪʃlɐ", en:"joiner, a furniture maker", pl:"Plural: die Tischler", ex:"Den Schrank haben wir uns vom Tischler machen lassen.", exEn:"We had the cupboard made by the joiner.", lv:3, field:"Trades and crafts", archaic:false, src:"https://de.wiktionary.org/wiki/Tischler"},
{w:"Habilitation", a:"die", pos:"noun · feminine", ipa:"habilitaˈt͡si̯oːn", en:"habilitation, the highest academic qualification", pl:"Plural: die Habilitationen", ex:"Die Fakultät befürwortete die Habilitation, und im Wintersemester 1908/09 erhielt Einstein die venia legendi.", exEn:"The faculty approved the habilitation, and in the winter semester of 1908/09 Einstein received the venia legendi (the right to teach).", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Habilitation"},
{w:"Lehrstuhl", a:"der", pos:"noun · masculine", ipa:"ˈleːɐ̯ˌʃtuːl", en:"professorial chair", pl:"Plural: die Lehrstühle", ex:"So habe das universitäre Fach Germanistik im Jahre 1949 nur noch in Budapest existiert, während die entsprechenden Lehrstühle in Szeged, Debrecen und Pécs aufgelöst worden seien.", exEn:"The university subject of German studies is said to have existed in 1949 only in Budapest, while the corresponding chairs in Szeged, Debrecen and Pécs had been dissolved.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Lehrstuhl"},
{w:"Dissertation", a:"die", pos:"noun · feminine", ipa:"dɪsɛʁtaˈt͡si̯oːn", en:"doctoral thesis", pl:"Plural: die Dissertationen", ex:"Er wird beeinflusst von seinem Lehrer, dem Philosophen Jacob Thomasius und erwirbt bei ihm 1663 mit der Dissertation „De principio individui“ den untersten akademischen Grad eines Bakkalaureus.", exEn:"Influenced by his teacher, the philosopher Jacob Thomasius, he earned the lowest academic degree of bachelor with the dissertation 'De principio individui' in 1663.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Dissertation"},
{w:"Immatrikulation", a:"die", pos:"noun · feminine", ipa:"ɪmatʁikulaˈt͡si̯oːn", en:"enrolment at a university", pl:"Plural: die Immatrikulationen", ex:"Ich studiere ab Oktober Medizin, die Immatrikulation ist aber Mitte September.", exEn:"I start studying medicine in October, but enrolment is in mid-September.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Immatrikulation"},
{w:"Exmatrikulation", a:"die", pos:"noun · feminine", ipa:"ɛksmatʁikulaˈt͡si̯oːn", en:"leaving the university register", pl:"Plural: die Exmatrikulationen", ex:"Die Exmatrikulation trete ex lege ohne einen neuerlich die Exmatrikulation verfügenden Verwaltungsakt ein.", exEn:"Exmatriculation takes effect by operation of law, without a further administrative act ordering it.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Exmatrikulation"},
{w:"Promotion", a:"die", pos:"noun · feminine", ipa:"ˌpʁomoˈt͡si̯oːn", en:"doctorate, gaining the doctoral degree", pl:"Plural: die Promotionen", ex:"Nach seiner Promotion ging er in die USA.", exEn:"After his doctorate he went to the USA.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Promotion"},
{w:"Fakultät", a:"die", pos:"noun · feminine", ipa:"fakʊlˈtɛːt", en:"faculty, a university department", pl:"Plural: die Fakultäten", ex:"Der Dekan begrüßt jedes Semester als Vorsteher der medizinischen Fakultät die neuen Studenten der Medizin.", exEn:"As head of the medical faculty, the dean welcomes the new medical students every semester.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Fakult%C3%A4t"},
{w:"Dekan", a:"der", pos:"noun · masculine", ipa:"deˈkaːn", en:"dean, head of a faculty", pl:"Plural: die Dekane", ex:"Dekane werden nur für eine begrenzte Zeit gewählt.", exEn:"Deans are elected for a limited term only.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Dekan"},
{w:"Rektor", a:"der", pos:"noun · masculine", ipa:"ˈʁɛktoːɐ̯", en:"rector, head of a university or school", pl:"Plural: die Rektoren", ex:"Der Rektor hält eine Rede zum Schuljahresbeginn.", exEn:"The headteacher gives a speech at the start of the school year.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Rektor"},
{w:"Vorlesung", a:"die", pos:"noun · feminine", ipa:"ˈfoːɐ̯ˌleːzʊŋ", en:"lecture at a university", pl:"Plural: die Vorlesungen", ex:"Zu den Vorlesungen komme ich immer pünktlich.", exEn:"I am always on time for lectures.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Vorlesung"},
{w:"Seminar", a:"das", pos:"noun · neuter", ipa:"zemiˈnaːɐ̯", en:"seminar, a participatory university class", pl:"Plural: die Seminare", ex:"Im letzten Semester habe ich ein Seminar über Spieltheorie besucht.", exEn:"Last semester I attended a seminar on game theory.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Seminar"},
{w:"Staatsexamen", a:"das", pos:"noun · neuter", ipa:"ˈʃtaːt͡sʔɛˌksaːmən", en:"state examination", pl:"Plural: die Staatsexamen", ex:"Beim ersten Staatsexamen fällt ein Drittel der Studenten durch, beim zweiten noch einmal ein Fünftel.", exEn:"A third of students fail the first state examination, and another fifth fail the second.", lv:3, field:"Academia", archaic:false, src:"https://de.wiktionary.org/wiki/Staatsexamen"},
{w:"Doktorvater", a:"der", pos:"noun · masculine", ipa:"ˈdɔktoːɐ̯ˌfaːtɐ", en:"doctoral supervisor", pl:"Plural: die Doktorväter", ex:"Ich habe meinen Doktorvater konsultiert.", exEn:"I consulted my doctoral supervisor.", note:"Example from DWDS; definition verified in German Wiktionary.", lv:3, field:"Academia", archaic:false, src:"https://www.dwds.de/wb/Doktorvater"},
{w:"Verwaltungsakt", a:"der", pos:"noun · masculine", ipa:"fɛɐ̯ˈvaltʊŋsˌʔakt", en:"administrative act, an official decision", pl:"Plural: die Verwaltungsakte", ex:"Der Widerspruch ist ein Rechtsbehelf gegen jede Art von Verwaltungsakten, der zunächst bei der Behörde, die den Verwaltungsakt erlassen hat, oder bei der nächsthöheren Behörde einzulegen ist, erst dann vor dem Verwaltungsgericht.", exEn:"An objection is a legal remedy against any kind of administrative act; it must first be lodged with the authority that issued the administrative act, or with the next higher authority, and only then before the administrative court.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Verwaltungsakt"},
{w:"Dienstweg", a:"der", pos:"noun · masculine", ipa:"ˈdiːnstˌveːk", en:"official channels, the prescribed route through authorities", pl:"Plural: die Dienstwege", ex:"Der Major, ein aktiver Offizier aus Karlsruhe, mit gutmütigem aufgeschwemmtem Trinkergesicht, sieht mich erstaunt an, ich habe den Dienstweg übersprungen, er müßte mich einsperren.", exEn:"The major, an active officer from Karlsruhe with a good-natured, bloated drinker's face, looks at me in astonishment; I have skipped the official channels, he would have to lock me up.", note:"Also the idiom 'auf dem kleinen Dienstweg', informally and off the record.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Dienstweg"},
{w:"Meldepflicht", a:"die", pos:"noun · feminine", ipa:"ˈmɛldəˌp͡flɪçt", en:"duty to report, mandatory notification", pl:"Plural: die Meldepflichten", ex:"Tollwut unterliegt der Meldepflicht.", exEn:"Rabies is a notifiable disease.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Meldepflicht"},
{w:"Verhältnismäßigkeit", a:"die", pos:"noun · feminine", ipa:"fɛɐ̯ˈhɛltnɪsˌmɛːsɪçkaɪ̯t", en:"proportionality, the proper balance of means", pl:"Plural: die Verhältnismäßigkeiten", ex:"In jedem Fall sollte die Verhältnismäßigkeit der Mittel gewahrt bleiben.", exEn:"In every case, the proportionality of the means should be preserved.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Verh%C3%A4ltnism%C3%A4%C3%9Figkeit"},
{w:"Widerspruch", a:"der", pos:"noun · masculine", ipa:"ˈviːdɐˌʃpʁʊx", en:"contradiction, formal objection", pl:"Plural: die Widersprüche", ex:"Der Artikel hat im dritten Absatz einen Widerspruch.", exEn:"The article contains a contradiction in its third paragraph.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Widerspruch"},
{w:"Bußgeld", a:"das", pos:"noun · neuter", ipa:"ˈbuːsˌɡɛlt", en:"fine for a minor offence", pl:"Plural: die Bußgelder", ex:"Weil ich mich versehentlich in die erste Klasse gesetzt hatte, musste ich ein Bußgeld in Höhe von 40 Euro zahlen.", exEn:"Because I had accidentally sat in first class, I had to pay a fine of 40 euros.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Bu%C3%9Fgeld"},
{w:"Ordnungswidrigkeit", a:"die", pos:"noun · feminine", ipa:"ˈɔʁdnʊŋsˌviːdʁɪçkaɪ̯t", en:"regulatory offence, minor breach of the law", pl:"Plural: die Ordnungswidrigkeiten", ex:"Das Fahren mit dem Fahrrad auf der linken Straßenseite stellt eine Ordnungswidrigkeit dar und kann mit einem Bußgeld geahndet werden.", exEn:"Riding a bicycle on the left-hand side of the road is a regulatory offence and can be punished with a fine.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Ordnungswidrigkeit"},
{w:"Verwaltungsgericht", a:"das", pos:"noun · neuter", ipa:"fɛɐ̯ˈvaltʊŋsɡəˌʁɪçt", en:"administrative court", pl:"Plural: die Verwaltungsgerichte", ex:"Das Verwaltungsgericht Köln hat am 8. März entschieden, dass das Bundesamt für den Verfassungsschutz die AfD als Verdachtsfall einstufen darf. […] Es gebe ausreichend Anhaltspunkte für verfassungsfeindliche Bestrebungen, befanden die Richter.", exEn:"On 8 March, the Cologne Administrative Court ruled that the Federal Office for the Protection of the Constitution may classify the AfD as a suspected case. The judges found there was sufficient evidence of anti-constitutional activities.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Verwaltungsgericht"},
{w:"Zuständigkeit", a:"die", pos:"noun · feminine", ipa:"ˈt͡suːˌʃtɛndɪçkaɪ̯t", en:"jurisdiction, responsibility", pl:"Plural: die Zuständigkeiten", ex:"Also fällt der Unfallort in seine Zuständigkeit.", exEn:"So the accident site falls within his jurisdiction.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Zust%C3%A4ndigkeit"},
{w:"Besoldung", a:"die", pos:"noun · feminine", ipa:"bəˈzɔldʊŋ", en:"pay for civil servants", pl:"Plural: die Besoldungen", ex:"Die Besoldung hält mit der Inflationsrate nicht mehr Schritt.", exEn:"Pay is no longer keeping pace with inflation.", lv:3, field:"Bureaucracy and administration", archaic:false, src:"https://de.wiktionary.org/wiki/Besoldung"},
{w:"Leitmotiv", a:"das", pos:"noun · neuter", ipa:"ˈlaɪ̯tmoˌtiːf", en:"leitmotif, a recurring musical theme", pl:"Plural: die Leitmotive", ex:"Der Begriff des Leitmotivs tauchte erstmals 1871 in Friedrich Wilhelm Jähns’ Verzeichnis der Werke Carl Maria von Webers auf.", exEn:"The term leitmotif first appeared in 1871 in Friedrich Wilhelm Jähns' catalogue of the works of Carl Maria von Weber.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Leitmotiv"},
{w:"Bildungsroman", a:"der", pos:"noun · masculine", ipa:"ˈbɪldʊŋsʁoˌmaːn", en:"novel of formation, a coming-of-age novel", pl:"Plural: die Bildungsromane", ex:"Goethes „Wilhelm Meisters Lehrjahre“ gilt als erster Bildungsroman.", exEn:"Goethe's 'Wilhelm Meister's Apprenticeship' is considered the first novel of formation.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Bildungsroman"},
{w:"Kontrapunkt", a:"der", pos:"noun · masculine", ipa:"ˈkɔntʁapʊŋkt", en:"counterpoint, independent voices in music", pl:"Plural: die Kontrapunkte", ex:"Der Kontrapunkt als Kompositionstechnik unterlag in der Musikgeschichte sich wandelnden Regeln, die von der wechselnden Bewertung von Konsonanzen und Dissonanzen abhingen.", exEn:"As a compositional technique, counterpoint was subject to changing rules in music history, depending on how consonances and dissonances were valued.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Kontrapunkt"},
{w:"Libretto", a:"das", pos:"noun · neuter", ipa:"liˈbʁɛto", en:"libretto, the text of an opera", pl:"Plural: die Librettos", ex:"Die Pianistin und Komponistin Clara Schumann bat sie, das Libretto für eine Oper ihres Mannes Robert zu schreiben.", exEn:"The pianist and composer Clara Schumann asked her to write the libretto for an opera by her husband Robert.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Libretto"},
{w:"Expressionismus", a:"der", pos:"noun · masculine", ipa:"ɛkspʁɛsi̯oˈnɪsmʊs", en:"Expressionism, early 20th-century art movement", pl:"No plural", ex:"Insbesondere junge Literaten des Expressionismus machten ihrem Verdruß über die verknöcherte Gesellschaft durch Herbeirufen der Apokalypse Luft.", exEn:"Young writers of Expressionism in particular vented their annoyance at ossified society by invoking the apocalypse.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Expressionismus"},
{w:"Jugendstil", a:"der", pos:"noun · masculine", ipa:"ˈjuːɡn̩tˌʃtiːl", en:"Art Nouveau, the style of around 1900", pl:"No plural", ex:"Der Tscheche Alphonse Mucha und der Österreicher Gustav Klimt sind hervorragende Repräsentanten des Jugendstiles.", exEn:"The Czech Alphonse Mucha and the Austrian Gustav Klimt are outstanding representatives of Art Nouveau.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Jugendstil"},
{w:"Atonalität", a:"die", pos:"noun · feminine", ipa:"ˌatonaliˈtɛːt", en:"atonality, music without a tonal centre", pl:"Plural: die Atonalitäten", ex:"Arnold Schönbergs (1874–1951) Form von neuer Musik – Atonalität und daraus folgend die Zwölftontechnik – zerbricht jede Harmonie, löst jede tonale Bindung auf, so wie sich in der Malerei das Gegenständliche auflöst.", exEn:"Arnold Schoenberg's (1874-1951) form of new music, atonality and the twelve-tone technique that followed from it, shatters all harmony and dissolves every tonal bond, just as representational subject matter dissolves in painting.", lv:3, field:"Music and arts", archaic:false, src:"https://de.wiktionary.org/wiki/Atonalit%C3%A4t"},
{w:"Minne", a:"die", pos:"noun · feminine", ipa:"ˈmɪnə", en:"courtly love, medieval love", pl:"No plural", ex:"Die Minne ist ein häufig in der Literatur des Mittelalters anzutreffendes Thema.", exEn:"Courtly love is a theme frequently found in medieval literature.", note:"Middle High German minne; the sense is labelled veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Minne"},
{w:"Buhle", a:"der", pos:"noun · masculine", ipa:"ˈbuːlə", en:"lover, sweetheart (archaic)", pl:"Plural: die Buhlen", ex:"Sie hat sich doch tatsächlich einen Grafen zum Buhlen genommen.", exEn:"She really has taken a count as her lover.", note:"Labelled gehoben, veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Buhle"},
{w:"Hagestolz", a:"der", pos:"noun · masculine", ipa:"ˈhaːɡəˌʃtɔlt͡s", en:"confirmed bachelor (archaic)", pl:"Plural: die Hagestolze", ex:"Da er sich nie zur Heirat entschließen konnte, war aus ihm schließlich ein Hagestolz geworden.", exEn:"Since he could never bring himself to marry, he had finally become a confirmed bachelor.", note:"Example from DWDS; definition verified in German Wiktionary. From Middle High German hagestolz, an unmarried man.", lv:3, field:"Archaic", archaic:true, src:"https://www.dwds.de/wb/Hagestolz"},
{w:"Oheim", a:"der", pos:"noun · masculine", ipa:"ˈoːhaɪ̯m", en:"uncle, mother's brother (archaic)", pl:"Plural: die Oheime", ex:"Eines Sonntags – es war am 24. Mai 1863 – kehrte mein Oheim, Professor Lidenbrock, in aller Eile in sein kleines Haus in der Königstraße Nr. 19, einer der ältesten Straßen Alt-Hamburgs, zurück.", exEn:"One Sunday, it was 24 May 1863, my uncle, Professor Lidenbrock, returned in great haste to his small house at Königstraße No. 19, one of the oldest streets in old Hamburg.", note:"Labelled veraltet in Wiktionary; originally only the mother's brother.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Oheim"},
{w:"Muhme", a:"die", pos:"noun · feminine", ipa:"ˈmuːmə", en:"aunt, mother's sister (archaic)", pl:"Plural: die Muhmen", ex:"Heute kommt die Muhme zu Besuch.", exEn:"My aunt is coming to visit today.", note:"Labelled veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Muhme"},
{w:"Gevatter", a:"der", pos:"noun · masculine", ipa:"ɡəˈfatɐ", en:"godfather, close companion (archaic)", pl:"Plural: die Gevattern", ex:"Er legte sich ins Gras, schloss die Augen und sah in der Ferne Gevatter Tod, der es eilig hatte.", exEn:"He lay down in the grass, closed his eyes and saw in the distance Godfather Death, who was in a hurry.", note:"From Latin compater, co-father; the godfather sense is labelled veraltend oder veraltet.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Gevatter"},
{w:"Mamsell", a:"die", pos:"noun · feminine", ipa:"mamˈzɛl", en:"housekeeper, unmarried lady (archaic)", pl:"Plural: die Mamsellen", ex:"Die Mägde waren der Mamsell unterstellt.", exEn:"The maids were under the housekeeper's authority.", note:"Example from DWDS; definition verified in German Wiktionary. The housekeeper and unmarried-lady senses are labelled veraltet.", lv:3, field:"Archaic", archaic:true, src:"https://www.dwds.de/wb/Mamsell"},
{w:"Gesinde", a:"das", pos:"noun · neuter", ipa:"ɡəˈzɪndə", en:"servants of a household or estate (archaic)", pl:"Plural: die Gesinde", ex:"Das Gesinde bekam seinen Lohn und wechselte den Dienstherren.", exEn:"The servants received their wages and changed employers.", note:"Labelled veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Gesinde"},
{w:"Kemenate", a:"die", pos:"noun · feminine", ipa:"kemeˈnaːtə", en:"heated chamber in a castle (archaic)", pl:"Plural: die Kemenaten", ex:"Er liebte es, in seiner stillen Kemenate zu sitzen.", exEn:"He loved sitting in his quiet little chamber.", note:"Example from DWDS; definition verified in German Wiktionary. The castle sense is labelled veraltet.", lv:3, field:"Archaic", archaic:true, src:"https://www.dwds.de/wb/Kemenate"},
{w:"hold", pos:"adjective", ipa:"hɔlt", en:"lovely, gracious (archaic)", ex:"Sie war eine holde Maid.", exEn:"She was a lovely maiden.", note:"Labelled gehoben, veraltend in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/hold"},
{w:"wacker", pos:"adjective", ipa:"ˈvakɐ", en:"brave, stout, valiant (archaic)", ex:"Sie hat wacker durchgehalten.", exEn:"She held out bravely.", note:"Labelled veraltend in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/wacker"},
{w:"Knecht", a:"der", pos:"noun · masculine", ipa:"knɛçt", en:"farmhand, manservant (archaic)", pl:"Plural: die Knechte", ex:"Es ist noch früh, hauptsächlich sind Knechte und Mägde da.", exEn:"It is still early; mainly farmhands and maids are about.", note:"Labelled veraltend in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Knecht"},
{w:"Lehen", a:"das", pos:"noun · neuter", ipa:"ˈleːən", en:"fief, land granted by a lord (archaic)", pl:"Plural: die Lehen", ex:"Der Kaiser vergab an seinen treuen Gefolgsmann ein Lehen.", exEn:"The emperor granted a fief to his loyal follower.", note:"The fief sense is labelled historisch and the loan senses veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Lehen"},
{w:"Gaukler", a:"der", pos:"noun · masculine", ipa:"ˈɡaʊ̯klɐ", en:"juggler, travelling performer (archaic)", pl:"Plural: die Gaukler", ex:"Dichter trugen Poeme vor, Gaukler zeigten ihre Geschicklichkeit, Händler boten Waren an, Bier wurde ausgeschenkt.", exEn:"Poets recited poems, jugglers showed off their skill, traders offered goods, beer was served.", note:"The performer sense is labelled veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Gaukler"},
{w:"Vetter", a:"der", pos:"noun · masculine", ipa:"ˈfɛtɐ", en:"cousin, originally father's brother's son (archaic)", pl:"Plural: die Vettern", ex:"Der Vetter aus München ist letztes Jahr verstorben.", exEn:"The cousin from Munich died last year.", note:"The older kinship senses are labelled veraltet in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Vetter"},
{w:"Kerker", a:"der", pos:"noun · masculine", ipa:"ˈkɛʁkɐ", en:"dungeon, prison (archaic)", pl:"Plural: die Kerker", ex:"Sie hielten ihn im Kerker gefangen.", exEn:"They held him prisoner in the dungeon.", note:"Labelled veraltend, historisch in Wiktionary.", lv:3, field:"Archaic", archaic:true, src:"https://de.wiktionary.org/wiki/Kerker"}
